"""Freeze the selected upstream archive's identities and parameter-menu reference."""

import argparse
import hashlib
import tarfile
from pathlib import Path

PIN = '540cda20a0c15982c5a3c5bdefab275f3e343c43'
PREFIX = f'gui-components-{PIN}/'
PARAMETER = 'src/EasyApplication/Gui/Components/ListViewParameter.qml'


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('archive', type=Path)
    args = parser.parse_args()
    with tarfile.open(args.archive) as archive:
        files = {
            member.name.removeprefix(PREFIX): archive.extractfile(member).read()
            for member in archive.getmembers()
            if member.isfile() and member.name.startswith(PREFIX + 'src/')
        }
    if PARAMETER not in files:
        raise SystemExit('The archive does not contain the selected upstream parameter cell')
    tree = ''.join(
        f'{path.removeprefix("src/")} {hashlib.sha256(data).hexdigest()}\n'
        for path, data in sorted(files.items())
    )
    target = Path(__file__).parent
    values = {
        'PIN': PIN,
        'ARCHIVE_SHA256': hashlib.sha256(args.archive.read_bytes()).hexdigest(),
        'SOURCE_SHA256': hashlib.sha256(tree.encode()).hexdigest(),
        'PARAMETER_SHA256': hashlib.sha256(files[PARAMETER]).hexdigest(),
    }
    (target / 'gui_base.py').write_text(
        '"""Upstream archive identities; generated by generate_gui_reference.py."""\n\n'
        + ''.join(f'{key} = {value!r}\n' for key, value in values.items())
    )
    (target / 'ListViewParameter.qml').write_bytes(files[PARAMETER])
    print(values)


if __name__ == '__main__':
    main()
